use vstd::prelude::*;

verus! {
    /// Returns 1.0 on the diagonal, 0.0 off it.
    fn diag_val(i: usize, j: usize) -> f64
        ensures
            // Exactly matches the text‐book definition of the Kronecker delta:
            (i == j  &&  result == 1.0) ||
            (i != j  &&  result == 0.0)
    {
        if i == j {
            1.0
        } else {
            0.0
        }
    }

    /// Builds the n×n identity matrix.
    fn identity(n: usize) -> Vec<Vec<f64>>
        ensures
            // It has n rows...
            result.len() == n,
            // ...each of length n...
            forall |i: usize| i < n ==> result[i].len() == n,
            // ...and the (i,j)-entry is diag_val(i,j).
            forall |i: usize, j: usize|
                i < n && j < n ==>
                    result[i][j] == diag_val(i, j)
    {
        (0..n)
            .map(|i| {
                (0..n)
                    .map(|j| diag_val(i, j))
                    .collect::<Vec<f64>>()
            })
            .collect::<Vec<Vec<f64>>>()
    }

    fn main() {
        // A quick smoke test:
        let m = identity(4);
        for row in m {
            // We know from our spec that each row is length 4 and
            // has exactly one 1.0 in the diagonal position.
            println!("{:?}", row);
        }
    }
}